/* ============================================================================
   ExamPro LMS - Area and Volume Course Seed Script (Unified Bilingual Model)
   - 1 Course: Area and Volume / பரப்பளவு மற்றும் கன அளவு
   - 2 Assessments (Single unified assessment for both English & Tamil):
       1. Area and Volume - Practice Set (area-and-volume-practice) [55 Questions]
          (25 Worked Examples + 30 Independent Practice in both English & Tamil)
       2. Area and Volume - Graded Assessment (area-and-volume-graded) [30 Questions]
          (Assessment Questions 1-30 in both English & Tamil)
   ============================================================================ */
USE ExamProLMS;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- Step 1: Ensure bilingual columns exist in dbo.Assessments & dbo.Questions
IF COL_LENGTH(N'dbo.Assessments', N'TitleTa') IS NULL
    ALTER TABLE dbo.Assessments ADD TitleTa NVARCHAR(200) NULL;
IF COL_LENGTH(N'dbo.Assessments', N'DescriptionTa') IS NULL
    ALTER TABLE dbo.Assessments ADD DescriptionTa NVARCHAR(MAX) NULL;
IF COL_LENGTH(N'dbo.Questions', N'QuestionTextTa') IS NULL
    ALTER TABLE dbo.Questions ADD QuestionTextTa NVARCHAR(MAX) NULL;
IF COL_LENGTH(N'dbo.Questions', N'OptionsJsonTa') IS NULL
    ALTER TABLE dbo.Questions ADD OptionsJsonTa NVARCHAR(MAX) NULL;
IF COL_LENGTH(N'dbo.Questions', N'ExplanationTa') IS NULL
    ALTER TABLE dbo.Questions ADD ExplanationTa NVARCHAR(MAX) NULL;
GO

BEGIN TRANSACTION;

-- Clean previous Area and Volume courses and assessments if present
DELETE FROM dbo.Assessments WHERE Slug IN (
    N'area-and-volume-practice', N'area-and-volume-graded',
    N'area-volume-practice', N'area-volume-graded',
    N'area-and-volume-practice-en', N'area-and-volume-graded-en',
    N'area-and-volume-practice-ta', N'area-and-volume-graded-ta'
);
DELETE FROM dbo.Courses WHERE Slug IN (N'area-and-volume', N'area-volume');

VALUES (
    N'Area and Volume / பரப்பளவு மற்றும் கன அளவு',
    N'area-and-volume',
    N'Comprehensive mensuration module on Area, Volume, Surface Area, Perimeter, and Scale Factors for TNPSC Group 1, UPSC CSAT, SSC CGL & Banking exams in English & Tamil.',
    4
);

DECLARE @CourseId INT = SCOPE_IDENTITY();

-- Insert ONLY 2 Assessments: 1 Practice (55 Questions) and 1 Graded (30 Questions)
    CourseId, Title, TitleTa, Slug, Description, DescriptionTa, Topic, Difficulty,
    DefaultDurationMinutes, MinDurationMinutes, TotalQuestions, PassPercentage,
    AttemptType, SequentialUnlock, LockdownEnabled, ProctoringEnabled, OrderIndex
)
VALUES
    (@CourseId, N'Area and Volume - Practice Set', N'பரப்பளவு மற்றும் கன அளவு - பயிற்சித் தொகுப்பு', N'area-and-volume-practice',
     N'55 practice questions (Worked Examples + Independent Practice) with instant feedback & step-by-step solutions.',
     N'55 பயிற்சிக் கணக்குகள் (தீர்க்கப்பட்ட எடுத்துக்காட்டுகள் + சுயப்பயிற்சி) உடனடித் தீர்வுகளுடன்.',
     N'Area and Volume', N'EASY', 60, 10, 55, 0, N'PRACTICE', 0, 0, 0, 1),
    (@CourseId, N'Area and Volume - Graded Assessment', N'பரப்பளவு மற்றும் கன அளவு - மதிப்பீட்டுத் தேர்வு', N'area-and-volume-graded',
     N'Official proctored & timed assessment on Area and Volume (30 Questions). Pass with 60% to master this topic.',
     N'பரப்பளவு மற்றும் கன அளவுக்கான அதிகாரப்பூர்வக் கண்காணிப்புடன் கூடிய தேர்வு (30 வினாக்கள்). தேர்ச்சி 60%.',
     N'Area and Volume', N'MEDIUM', 45, 15, 30, 60, N'GRADED', 1, 1, 1, 2);

DECLARE @pracId INT = (SELECT AssessmentId FROM dbo.Assessments WHERE Slug = N'area-and-volume-practice');
DECLARE @gradId INT = (SELECT AssessmentId FROM dbo.Assessments WHERE Slug = N'area-and-volume-graded');

-- Insert bilingual questions for @pracId (55 questions)

