INSERT INTO dbo.Assessments (
INSERT INTO dbo.Questions (AssessmentId, QuestionText, OptionsJson, CorrectIndex, Explanation, QuestionTextTa, OptionsJsonTa, ExplanationTa, Topic, Difficulty, OrderIndex)
VALUES
    (@pracId, N'Find the area of a rectangle with length 12 m and breadth 8 m.', N'["84 sq. m", "90 sq. m", "96 sq. m", "100 sq. m"]', 2, N'Area = 12 × 8 = 96 sq. m. Key Learning Point: Area of a rectangle = length × breadth.', N'நீளம் 12 மீ, அகலம் 8 மீ கொண்ட ஒரு செவ்வகத்தின் பரப்பளவைக் காண்க.', N'["84 ச.மீ", "90 ச.மீ", "96 ச.மீ", "100 ச.மீ"]', N'பரப்பளவு = 12 × 8 = 96 ச.மீ. முக்கியக் கற்றல் கருத்து: செவ்வகத்தின் பரப்பளவு = நீளம் × அகலம்.', N'Area and Volume', N'EASY', 1),
    (@pracId, N'Find the area of a square with side 15 cm.', N'["200 sq. cm", "210 sq. cm", "225 sq. cm", "240 sq. cm"]', 2, N'Area = 15² = 225 sq. cm. Key Learning Point: Area of a square = side².', N'பக்கம் 15 செ.மீ கொண்ட ஒரு சதுரத்தின் பரப்பளவைக் காண்க.', N'["200 ச.செ.மீ", "210 ச.செ.மீ", "225 ச.செ.மீ", "240 ச.செ.மீ"]', N'பரப்பளவு = 15² = 225 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: சதுரத்தின் பரப்பளவு = பக்கம்².', N'Area and Volume', N'EASY', 2),
    (@pracId, N'Find the volume of a cube with side 6 cm.', N'["196 cubic cm", "200 cubic cm", "210 cubic cm", "216 cubic cm"]', 3, N'Volume = 6³ = 216 cubic cm. Key Learning Point: Volume of a cube = side³.', N'பக்கம் 6 செ.மீ கொண்ட ஒரு கனசதுரத்தின் கன அளவைக் காண்க.', N'["196 க.செ.மீ", "200 க.செ.மீ", "210 க.செ.மீ", "216 க.செ.மீ"]', N'கன அளவு = 6³ = 216 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் கன அளவு = பக்கம்³.', N'Area and Volume', N'EASY', 3),
    (@pracId, N'Find the area of a circle with radius 7 cm. (π = 22/7)', N'["144 sq. cm", "154 sq. cm", "164 sq. cm", "174 sq. cm"]', 1, N'Area = 22/7 × 7² = 154 sq. cm. Key Learning Point: Area of a circle = πr².', N'ஆரம் 7 செ.மீ கொண்ட ஒரு வட்டத்தின் பரப்பளவைக் காண்க. (π = 22/7)', N'["144 ச.செ.மீ", "154 ச.செ.மீ", "164 ச.செ.மீ", "174 ச.செ.மீ"]', N'பரப்பளவு = 22/7 × 7² = 154 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: வட்டத்தின் பரப்பளவு = πr².', N'Area and Volume', N'EASY', 4),
    (@pracId, N'Find the volume of a cuboid with dimensions 10 cm × 5 cm × 4 cm.', N'["180 cubic cm", "190 cubic cm", "200 cubic cm", "210 cubic cm"]', 2, N'Volume = 10 × 5 × 4 = 200 cubic cm. Key Learning Point: Volume of a cuboid = length × breadth × height.', N'10 செ.மீ × 5 செ.மீ × 4 செ.மீ அளவுள்ள ஒரு கனச்செவ்வகத்தின் கன அளவைக் காண்க.', N'["180 க.செ.மீ", "190 க.செ.மீ", "200 க.செ.மீ", "210 க.செ.மீ"]', N'கன அளவு = 10 × 5 × 4 = 200 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் கன அளவு = நீளம் × அகலம் × உயரம்.', N'Area and Volume', N'EASY', 5),
    (@pracId, N'A rectangular park is 60 m long and 40 m wide. A path 2 m wide runs around it (outside). Find the area of the path.', N'["396 sq. m", "406 sq. m", "416 sq. m", "426 sq. m"]', 2, N'Outer dimensions = 64 × 44 = 2816 sq. m. Inner area = 60 × 40 = 2400 sq. m. Path area = 2816 − 2400 = 416 sq. m. Key Learning Point: For a path around a figure, compute the outer and inner areas separately, then subtract.', N'ஒரு செவ்வகப் பூங்கா 60 மீ நீளமும் 40 மீ அகலமும் கொண்டது. அதைச் சுற்றி (வெளிப்புறமாக) 2 மீ அகலமுள்ள ஒரு பாதை உள்ளது. பாதையின் பரப்பளவைக் காண்க.', N'["396 ச.மீ", "406 ச.மீ", "416 ச.மீ", "426 ச.மீ"]', N'வெளி அளவுகள் = 64 × 44 = 2816 ச.மீ. உள்பரப்பளவு = 60 × 40 = 2400 ச.மீ. பாதையின் பரப்பளவு = 2816 − 2400 = 416 ச.மீ. முக்கியக் கற்றல் கருத்து: ஓர் உருவத்தைச் சுற்றியுள்ள பாதைக்கு, வெளிப் பரப்பளவையும் உள் பரப்பளவையும் தனித்தனியாகக் கணக்கிட்டுக் கழிக்கவும்.', N'Area and Volume', N'MEDIUM', 6),
    (@pracId, N'The circumference of a circular garden is 44 m. Find its area. (π = 22/7)', N'["144 sq. m", "154 sq. m", "164 sq. m", "174 sq. m"]', 1, N'2πr = 44 → r = 44 × 7/(2×22) = 7 m. Area = 22/7 × 49 = 154 sq. m. Key Learning Point: Find the radius from the circumference first, then apply the area formula.', N'ஒரு வட்ட வடிவத் தோட்டத்தின் சுற்றளவு 44 மீ. அதன் பரப்பளவைக் காண்க. (π = 22/7)', N'["144 ச.மீ", "154 ச.மீ", "164 ச.மீ", "174 ச.மீ"]', N'2πr = 44 → r = 44 × 7/(2×22) = 7 மீ. பரப்பளவு = 22/7 × 49 = 154 ச.மீ. முக்கியக் கற்றல் கருத்து: முதலில் சுற்றளவிலிருந்து ஆரத்தைக் கண்டறிந்து, பின்னர் பரப்பளவுச் சூத்திரத்தைப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 7),
    (@pracId, N'A cylindrical tank has radius 7 m and height 10 m. Find its volume. (π = 22/7)', N'["1440 cubic m", "1500 cubic m", "1540 cubic m", "1600 cubic m"]', 2, N'Volume = 22/7 × 49 × 10 = 1540 cubic m. Key Learning Point: Volume of a cylinder = πr²h.', N'ஓர் உருளை வடிவத் தொட்டியின் ஆரம் 7 மீ, உயரம் 10 மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["1440 க.மீ", "1500 க.மீ", "1540 க.மீ", "1600 க.மீ"]', N'கன அளவு = 22/7 × 49 × 10 = 1540 க.மீ. முக்கியக் கற்றல் கருத்து: உருளையின் கன அளவு = πr²h.', N'Area and Volume', N'EASY', 8),
    (@pracId, N'Find the total surface area of a cube with edge 9 cm.', N'["456 sq. cm", "468 sq. cm", "480 sq. cm", "486 sq. cm"]', 3, N'TSA = 6a² = 6 × 81 = 486 sq. cm. Key Learning Point: Total surface area of a cube = 6 × (edge)².', N'விளிம்பு 9 செ.மீ கொண்ட ஒரு கனசதுரத்தின் மொத்தப் புறப்பரப்பைக் காண்க.', N'["456 ச.செ.மீ", "468 ச.செ.மீ", "480 ச.செ.மீ", "486 ச.செ.மீ"]', N'மொத்தப் புறப்பரப்பு = 6a² = 6 × 81 = 486 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் மொத்தப் புறப்பரப்பு = 6 × (விளிம்பு)².', N'Area and Volume', N'EASY', 9),
    (@pracId, N'A cone has radius 7 cm and slant height 25 cm. Find its curved surface area. (π = 22/7)', N'["520 sq. cm", "535 sq. cm", "550 sq. cm", "565 sq. cm"]', 2, N'CSA = πrl = 22/7 × 7 × 25 = 550 sq. cm. Key Learning Point: Curved surface area of a cone = πrl, where l is the slant height, not the vertical height.', N'ஒரு கூம்பின் ஆரம் 7 செ.மீ, சாய்வுயரம் 25 செ.மீ. அதன் வளைபரப்பைக் காண்க. (π = 22/7)', N'["520 ச.செ.மீ", "535 ச.செ.மீ", "550 ச.செ.மீ", "565 ச.செ.மீ"]', N'வளைபரப்பு = πrl = 22/7 × 7 × 25 = 550 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் வளைபரப்பு = πrl; இங்கு l என்பது செங்குத்து உயரம் அல்ல, சாய்வுயரம்.', N'Area and Volume', N'EASY', 10),
    (@pracId, N'Two cubes, each of volume 64 cubic cm, are joined end to end. Find the surface area of the resulting cuboid.', N'["150 sq. cm", "160 sq. cm", "170 sq. cm", "180 sq. cm"]', 1, N'Side of each cube = 4 cm (since 4³=64). Resulting cuboid = 8 × 4 × 4. SA = 2(32+16+32) = 160 sq. cm. Key Learning Point: When two cubes are joined, the two joined faces are no longer part of the outer surface – compute the resulting cuboid’s surface area directly rather than adding the cubes’ individual surface areas.', N'ஒவ்வொன்றும் 64 க.செ.மீ கன அளவுள்ள இரண்டு கனசதுரங்கள் முனையோடு முனையாக இணைக்கப்படுகின்றன. விளையும் கனச்செவ்வகத்தின் புறப்பரப்பைக் காண்க.', N'["150 ச.செ.மீ", "160 ச.செ.மீ", "170 ச.செ.மீ", "180 ச.செ.மீ"]', N'ஒவ்வொரு கனசதுரத்தின் பக்கம் = 4 செ.மீ (4³ = 64 என்பதால்). விளையும் கனச்செவ்வகம் = 8 × 4 × 4. புறப்பரப்பு = 2(32+16+32) = 160 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: இரண்டு கனசதுரங்கள் இணைக்கப்படும்போது, இணைந்த இரண்டு முகங்களும் வெளிப்பரப்பின் பகுதியாக இருப்பதில்லை – கனசதுரங்களின் தனிப் புறப்பரப்புகளைக் கூட்டுவதற்குப் பதிலாக, விளையும் கனச்செவ்வகத்தின் புறப்பரப்பை நேரடியாகக் கணக்கிடவும்.', N'Area and Volume', N'MEDIUM', 11),
    (@pracId, N'The radius of a sphere is 21 cm. Find its volume. (π = 22/7)', N'["36808 cubic cm", "37808 cubic cm", "38808 cubic cm", "39808 cubic cm"]', 2, N'Volume = 4/3 × 22/7 × 21³ = 4/3 × 22/7 × 9261 = 38808 cubic cm. Key Learning Point: Volume of a sphere = 4/3πr³.', N'ஒரு கோளத்தின் ஆரம் 21 செ.மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["36808 க.செ.மீ", "37808 க.செ.மீ", "38808 க.செ.மீ", "39808 க.செ.மீ"]', N'கன அளவு = 4/3 × 22/7 × 21³ = 4/3 × 22/7 × 9261 = 38808 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கோளத்தின் கன அளவு = 4/3πr³.', N'Area and Volume', N'EASY', 12),
    (@pracId, N'A rectangular tank 8 m × 6 m × 3 m is to be filled with water using a pipe of cross-section 0.1 sq. m, flowing at 2 m/s. Find the time to fill the tank.', N'["600 seconds", "660 seconds", "700 seconds", "720 seconds"]', 3, N'Volume = 8×6×3 = 144 cubic m. Flow rate = 0.1×2 = 0.2 cubic m/s. Time = 144/0.2 = 720 seconds. Key Learning Point: Time to fill = volume to be filled ÷ rate of flow.', N'8 மீ × 6 மீ × 3 மீ அளவுள்ள ஒரு செவ்வகத் தொட்டி, 0.1 ச.மீ குறுக்குவெட்டுப் பரப்புள்ள ஒரு குழாய் மூலம் வினாடிக்கு 2 மீ வேகத்தில் பாயும் நீரால் நிரப்பப்பட வேண்டும். தொட்டி நிரம்ப ஆகும் காலத்தைக் காண்க.', N'["600 வினாடிகள்", "660 வினாடிகள்", "700 வினாடிகள்", "720 வினாடிகள்"]', N'கன அளவு = 8×6×3 = 144 க.மீ. பாய்வு வீதம் = 0.1×2 = 0.2 க.மீ/வினாடி. காலம் = 144/0.2 = 720 வினாடிகள். முக்கியக் கற்றல் கருத்து: நிரம்பும் காலம் = நிரப்ப வேண்டிய கன அளவு ÷ பாய்வு வீதம்.', N'Area and Volume', N'MEDIUM', 13),
    (@pracId, N'The ratio of the radii of two spheres is 3:4. Find the ratio of their volumes.', N'["9:16", "27:64", "3:4", "64:27"]', 1, N'Volume ratio = (radius ratio)³ = 3³:4³ = 27:64. Key Learning Point: Volume scales as the cube of the linear scale factor.', N'இரண்டு கோளங்களின் ஆரங்களின் விகிதம் 3:4. அவற்றின் கன அளவுகளின் விகிதத்தைக் காண்க.', N'["9:16", "27:64", "3:4", "64:27"]', N'கன அளவு விகிதம் = (ஆர விகிதம்)³ = 3³:4³ = 27:64. முக்கியக் கற்றல் கருத்து: கன அளவு நீள அளவுமாற்றக் காரணியின் கனமாக மாறுகிறது.', N'Area and Volume', N'EASY', 14),
    (@pracId, N'A cylinder and a cone have equal radius (7 cm) and equal height (15 cm). Find the ratio of their volumes.', N'["1:3", "2:1", "3:1", "3:2"]', 2, N'Cylinder volume = πr²h. Cone volume = ⅓πr²h. Ratio = 3:1. Key Learning Point: For equal radius and height, a cylinder’s volume is always exactly three times a cone’s volume.', N'ஓர் உருளையும் ஒரு கூம்பும் சம ஆரமும் (7 செ.மீ) சம உயரமும் (15 செ.மீ) கொண்டவை. அவற்றின் கன அளவுகளின் விகிதத்தைக் காண்க.', N'["1:3", "2:1", "3:1", "3:2"]', N'உருளையின் கன அளவு = πr²h. கூம்பின் கன அளவு = ⅓πr²h. விகிதம் = 3:1. முக்கியக் கற்றல் கருத்து: சம ஆரமும் சம உயரமும் கொண்டால், உருளையின் கன அளவு எப்போதும் கூம்பின் கன அளவின் சரியாக மூன்று மடங்காகும்.', N'Area and Volume', N'EASY', 15),
    (@pracId, N'Find the volume of a hemisphere of radius 21 cm. (π = 22/7)', N'["18404 cubic cm", "19404 cubic cm", "20404 cubic cm", "21404 cubic cm"]', 1, N'Volume = 2/3 × 22/7 × 21³ = 2/3 × 22/7 × 9261 = 19404 cubic cm. Key Learning Point: A hemisphere’s volume is exactly half of a sphere’s volume with the same radius.', N'ஆரம் 21 செ.மீ கொண்ட ஓர் அரைக்கோளத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["18404 க.செ.மீ", "19404 க.செ.மீ", "20404 க.செ.மீ", "21404 க.செ.மீ"]', N'கன அளவு = 2/3 × 22/7 × 21³ = 2/3 × 22/7 × 9261 = 19404 க.செ.மீ. முக்கியக் கற்றல் கருத்து: அரைக்கோளத்தின் கன அளவு, அதே ஆரமுள்ள கோளத்தின் கன அளவில் சரியாகப் பாதியாகும்.', N'Area and Volume', N'EASY', 16),
    (@pracId, N'A rectangular sheet 44 cm × 20 cm is rolled to form a cylinder along its length (44 cm becomes the circumference). Find the radius. (π = 22/7)', N'["6 cm", "7 cm", "8 cm", "10 cm"]', 1, N'2πr = 44 → r = 44 × 7/(2×22) = 7 cm. Key Learning Point: When a sheet is rolled, one side becomes the circumference of the resulting cylinder’s base.', N'44 செ.மீ × 20 செ.மீ அளவுள்ள ஒரு செவ்வகத்தாள் அதன் நீளவாக்கில் சுருட்டப்பட்டு ஓர் உருளை ஆக்கப்படுகிறது (44 செ.மீ அடிச்சுற்றளவாகிறது). ஆரத்தைக் காண்க. (π = 22/7)', N'["6 செ.மீ", "7 செ.மீ", "8 செ.மீ", "10 செ.மீ"]', N'2πr = 44 → r = 44 × 7/(2×22) = 7 செ.மீ. முக்கியக் கற்றல் கருத்து: ஒரு தாள் சுருட்டப்படும்போது, அதன் ஒரு பக்கம் விளையும் உருளையின் அடிச்சுற்றளவாகிறது.', N'Area and Volume', N'EASY', 17),
    (@pracId, N'A solid cube of edge 12 cm is melted and recast into smaller cubes of edge 3 cm each. Find the number of smaller cubes.', N'["32", "48", "56", "64"]', 3, N'Number of smaller cubes = 12³/3³ = 1728/27 = 64. Key Learning Point: In melting-and-recasting problems, the total volume is conserved – divide the original volume by the new (smaller) unit’s volume.', N'விளிம்பு 12 செ.மீ கொண்ட ஒரு திண்மக் கனசதுரம் உருக்கப்பட்டு, ஒவ்வொன்றும் 3 செ.மீ விளிம்புடைய சிறிய கனசதுரங்களாக மறுவார்க்கப்படுகிறது. சிறிய கனசதுரங்களின் எண்ணிக்கையைக் காண்க.', N'["32", "48", "56", "64"]', N'சிறிய கனசதுரங்களின் எண்ணிக்கை = 12³/3³ = 1728/27 = 64. முக்கியக் கற்றல் கருத்து: உருக்கி மறுவார்ப்புக் கணக்குகளில் மொத்தக் கன அளவு மாறாது – மூலக் கன அளவைப் புதிய (சிறிய) அலகின் கன அளவால் வகுக்கவும்.', N'Area and Volume', N'EASY', 18),
    (@pracId, N'The area of a trapezium is 320 sq. cm with parallel sides 25 cm and 15 cm. Find the height.', N'["14 cm", "15 cm", "16 cm", "18 cm"]', 2, N'Area = ½(a+b)h → 320 = ½ × 40 × h → h = 16 cm. Key Learning Point: Area of a trapezium = ½ × (sum of parallel sides) × height.', N'ஒரு சரிவகத்தின் பரப்பளவு 320 ச.செ.மீ; அதன் இணைப்பக்கங்கள் 25 செ.மீ மற்றும் 15 செ.மீ. உயரத்தைக் காண்க.', N'["14 செ.மீ", "15 செ.மீ", "16 செ.மீ", "18 செ.மீ"]', N'பரப்பளவு = ½(a+b)h → 320 = ½ × 40 × h → h = 16 செ.மீ. முக்கியக் கற்றல் கருத்து: சரிவகத்தின் பரப்பளவு = ½ × (இணைப்பக்கங்களின் கூடுதல்) × உயரம்.', N'Area and Volume', N'EASY', 19),
    (@pracId, N'A right circular cone has base radius 7 cm and height 24 cm. Find its volume. (π = 22/7)', N'["1200 cubic cm", "1218 cubic cm", "1232 cubic cm", "1250 cubic cm"]', 2, N'Volume = ⅓ × 22/7 × 49 × 24 = ⅓ × 22 × 7 × 24 = 1232 cubic cm. Key Learning Point: Volume of a cone = ⅓πr²h – always use the vertical height, not the slant height, for volume.', N'ஒரு நேர்வட்டக் கூம்பின் அடி ஆரம் 7 செ.மீ, உயரம் 24 செ.மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["1200 க.செ.மீ", "1218 க.செ.மீ", "1232 க.செ.மீ", "1250 க.செ.மீ"]', N'கன அளவு = ⅓ × 22/7 × 49 × 24 = ⅓ × 22 × 7 × 24 = 1232 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் கன அளவு = ⅓πr²h – கன அளவுக்கு எப்போதும் சாய்வுயரம் அல்ல, செங்குத்து உயரத்தையே பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 20),
    (@pracId, N'A cylindrical pipe has internal radius 3 cm, external radius 5 cm, and length 14 cm. Find the volume of metal used. (π = 22/7)', N'["684 cubic cm", "694 cubic cm", "704 cubic cm", "714 cubic cm"]', 2, N'Volume of metal = π(R²−r²)h = 22/7 × (25−9) × 14 = 22/7 × 16 × 14 = 704 cubic cm. Key Learning Point: For a hollow cylinder, subtract the inner (hollow) volume from the outer volume using R² − r².', N'ஓர் உருளை வடிவக் குழாயின் உள் ஆரம் 3 செ.மீ, வெளி ஆரம் 5 செ.மீ, நீளம் 14 செ.மீ. பயன்படுத்தப்பட்ட உலோகத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["684 க.செ.மீ", "694 க.செ.மீ", "704 க.செ.மீ", "714 க.செ.மீ"]', N'உலோகத்தின் கன அளவு = π(R²−r²)h = 22/7 × (25−9) × 14 = 22/7 × 16 × 14 = 704 க.செ.மீ. முக்கியக் கற்றல் கருத்து: உள்ளீடற்ற உருளைக்கு, R² − r² ஐப் பயன்படுத்தி வெளிக் கன அளவிலிருந்து உள் (வெற்று) கன அளவைக் கழிக்கவும்.', N'Area and Volume', N'MEDIUM', 21),
    (@pracId, N'A room is 12 m long, 10 m wide, and 8 m high. Find the cost of whitewashing the walls and ceiling (excluding the floor) at ₹5 per sq. m.', N'["₹2260", "₹2360", "₹2460", "₹2560"]', 1, N'Wall area = 2h(l+b) = 2×8×22 = 352 sq. m. Ceiling area = 12×10 = 120 sq. m. Total = 472 sq. m. Cost = 472 × 5 = ₹2360. Key Learning Point: For whitewashing problems, identify exactly which surfaces are included (walls, ceiling, floor) before computing the total area.', N'ஓர் அறை 12 மீ நீளம், 10 மீ அகலம், 8 மீ உயரம் கொண்டது. ஒரு ச.மீ-க்கு ₹5 வீதம் சுவர்களுக்கும் மேற்கூரைக்கும் (தரை நீங்கலாக) வெள்ளையடிக்க ஆகும் செலவைக் காண்க.', N'["₹2260", "₹2360", "₹2460", "₹2560"]', N'சுவர்களின் பரப்பு = 2h(l+b) = 2×8×22 = 352 ச.மீ. மேற்கூரையின் பரப்பு = 12×10 = 120 ச.மீ. மொத்தம் = 472 ச.மீ. செலவு = 472 × 5 = ₹2360. முக்கியக் கற்றல் கருத்து: வெள்ளையடிக்கும் கணக்குகளில், மொத்தப் பரப்பைக் கணக்கிடும் முன் எந்தெந்தப் பரப்புகள் (சுவர்கள், மேற்கூரை, தரை) சேர்க்கப்பட்டுள்ளன என்பதைத் துல்லியமாக அடையாளம் காணவும்.', N'Area and Volume', N'MEDIUM', 22),
    (@pracId, N'A sphere of radius 6 cm is melted and recast into a cylinder of radius 4 cm. Find the height of the cylinder.', N'["16 cm", "18 cm", "20 cm", "24 cm"]', 1, N'Volume of sphere = 4/3π × 216 = 288π. Volume of cylinder = π × 16 × h = 16πh. 16h = 288 → h = 18 cm. Key Learning Point: In melting-and-recasting problems, equate the volume of the original solid to the volume of the new solid, and solve for the unknown dimension.', N'ஆரம் 6 செ.மீ கொண்ட ஒரு கோளம் உருக்கப்பட்டு, ஆரம் 4 செ.மீ கொண்ட ஓர் உருளையாக மறுவார்க்கப்படுகிறது. உருளையின் உயரத்தைக் காண்க.', N'["16 செ.மீ", "18 செ.மீ", "20 செ.மீ", "24 செ.மீ"]', N'கோளத்தின் கன அளவு = 4/3π × 216 = 288π. உருளையின் கன அளவு = π × 16 × h = 16πh. 16h = 288 → h = 18 செ.மீ. முக்கியக் கற்றல் கருத்து: உருக்கி மறுவார்ப்புக் கணக்குகளில், மூலத் திண்மத்தின் கன அளவைப் புதிய திண்மத்தின் கன அளவுடன் சமப்படுத்தி, தெரியாத அளவைக் காணவும்.', N'Area and Volume', N'MEDIUM', 23),
    (@pracId, N'The diagonal of a cube is 12√3 cm. Find its volume.', N'["1600 cubic cm", "1700 cubic cm", "1728 cubic cm", "1800 cubic cm"]', 2, N'Diagonal = a√3 → 12√3 = a√3 → a = 12. Volume = 12³ = 1728 cubic cm. Key Learning Point: The space diagonal of a cube equals side × √3 – use this to recover the side length first.', N'ஒரு கனசதுரத்தின் மூலைவிட்டம் 12√3 செ.மீ. அதன் கன அளவைக் காண்க.', N'["1600 க.செ.மீ", "1700 க.செ.மீ", "1728 க.செ.மீ", "1800 க.செ.மீ"]', N'மூலைவிட்டம் = a√3 → 12√3 = a√3 → a = 12. கன அளவு = 12³ = 1728 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் வெளி மூலைவிட்டம் = பக்கம் × √3 – இதைப் பயன்படுத்தி முதலில் பக்க நீளத்தைக் கண்டறியவும்.', N'Area and Volume', N'MEDIUM', 24),
    (@pracId, N'A well of diameter 14 m is dug 24 m deep. The earth taken out is spread evenly around it to form an embankment of width 7 m. Find the height of the embankment. (π = 22/7)', N'["6 m", "7 m", "8 m", "9 m"]', 2, N'Well: r=7, depth=24. Volume of earth = 22/7 × 49 × 24 = 3696 cubic m. Embankment: inner radius 7, outer radius 14. Area = 22/7 × (196−49) = 462 sq. m. Height = 3696 ÷ 462 = 8 m. Key Learning Point: The volume of earth dug from the well equals the volume of the embankment ring – set the two equal and solve for the unknown height.', N'14 மீ விட்டமுள்ள ஒரு கிணறு 24 மீ ஆழத்திற்குத் தோண்டப்படுகிறது. தோண்டிய மண் அதைச் சுற்றிச் சீராகப் பரப்பப்பட்டு 7 மீ அகலமுள்ள ஒரு கரை அமைக்கப்படுகிறது. கரையின் உயரத்தைக் காண்க. (π = 22/7)', N'["6 மீ", "7 மீ", "8 மீ", "9 மீ"]', N'கிணறு: r=7, ஆழம்=24. மண்ணின் கன அளவு = 22/7 × 49 × 24 = 3696 க.மீ. கரை: உள் ஆரம் 7, வெளி ஆரம் 14. பரப்பு = 22/7 × (196−49) = 462 ச.மீ. உயரம் = 3696 ÷ 462 = 8 மீ. முக்கியக் கற்றல் கருத்து: கிணற்றிலிருந்து தோண்டிய மண்ணின் கன அளவு கரை வளையத்தின் கன அளவுக்குச் சமம் – இரண்டையும் சமப்படுத்தித் தெரியாத உயரத்தைக் காணவும்.', N'Area and Volume', N'HARD', 25),
    (@pracId, N'Find the area of a rectangle with length 18 m and breadth 9 m.', N'["152 sq. m", "158 sq. m", "162 sq. m", "168 sq. m"]', 2, N'Area = 18 × 9 = 162 sq. m. Key Learning Point: Area of a rectangle = length × breadth.', N'நீளம் 18 மீ, அகலம் 9 மீ கொண்ட ஒரு செவ்வகத்தின் பரப்பளவைக் காண்க.', N'["152 ச.மீ", "158 ச.மீ", "162 ச.மீ", "168 ச.மீ"]', N'பரப்பளவு = 18 × 9 = 162 ச.மீ. முக்கியக் கற்றல் கருத்து: செவ்வகத்தின் பரப்பளவு = நீளம் × அகலம்.', N'Area and Volume', N'EASY', 26),
    (@pracId, N'Find the area of a square with side 21 cm.', N'["421 sq. cm", "431 sq. cm", "441 sq. cm", "451 sq. cm"]', 2, N'Area = 21² = 441 sq. cm. Key Learning Point: Area of a square = side².', N'பக்கம் 21 செ.மீ கொண்ட ஒரு சதுரத்தின் பரப்பளவைக் காண்க.', N'["421 ச.செ.மீ", "431 ச.செ.மீ", "441 ச.செ.மீ", "451 ச.செ.மீ"]', N'பரப்பளவு = 21² = 441 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: சதுரத்தின் பரப்பளவு = பக்கம்².', N'Area and Volume', N'EASY', 27),
    (@pracId, N'Find the volume of a cube with side 5 cm.', N'["100 cubic cm", "110 cubic cm", "120 cubic cm", "125 cubic cm"]', 3, N'Volume = 5³ = 125 cubic cm. Key Learning Point: Volume of a cube = side³.', N'பக்கம் 5 செ.மீ கொண்ட ஒரு கனசதுரத்தின் கன அளவைக் காண்க.', N'["100 க.செ.மீ", "110 க.செ.மீ", "120 க.செ.மீ", "125 க.செ.மீ"]', N'கன அளவு = 5³ = 125 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் கன அளவு = பக்கம்³.', N'Area and Volume', N'EASY', 28),
    (@pracId, N'Find the area of a circle with radius 14 cm. (π = 22/7)', N'["596 sq. cm", "606 sq. cm", "616 sq. cm", "626 sq. cm"]', 2, N'Area = 22/7 × 196 = 616 sq. cm. Key Learning Point: Area of a circle = πr².', N'ஆரம் 14 செ.மீ கொண்ட ஒரு வட்டத்தின் பரப்பளவைக் காண்க. (π = 22/7)', N'["596 ச.செ.மீ", "606 ச.செ.மீ", "616 ச.செ.மீ", "626 ச.செ.மீ"]', N'பரப்பளவு = 22/7 × 196 = 616 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: வட்டத்தின் பரப்பளவு = πr².', N'Area and Volume', N'EASY', 29),
    (@pracId, N'Find the volume of a cuboid with dimensions 12 cm × 6 cm × 5 cm.', N'["340 cubic cm", "350 cubic cm", "360 cubic cm", "370 cubic cm"]', 2, N'Volume = 12 × 6 × 5 = 360 cubic cm. Key Learning Point: Volume of a cuboid = length × breadth × height.', N'12 செ.மீ × 6 செ.மீ × 5 செ.மீ அளவுள்ள ஒரு கனச்செவ்வகத்தின் கன அளவைக் காண்க.', N'["340 க.செ.மீ", "350 க.செ.மீ", "360 க.செ.மீ", "370 க.செ.மீ"]', N'கன அளவு = 12 × 6 × 5 = 360 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் கன அளவு = நீளம் × அகலம் × உயரம்.', N'Area and Volume', N'EASY', 30),
    (@pracId, N'Find the total surface area of a cuboid 10 cm × 8 cm × 6 cm.', N'["356 sq. cm", "366 sq. cm", "376 sq. cm", "386 sq. cm"]', 2, N'TSA = 2(lb+bh+hl) = 2(80+48+60) = 376 sq. cm. Key Learning Point: Total surface area of a cuboid = 2(lb + bh + hl).', N'10 செ.மீ × 8 செ.மீ × 6 செ.மீ அளவுள்ள ஒரு கனச்செவ்வகத்தின் மொத்தப் புறப்பரப்பைக் காண்க.', N'["356 ச.செ.மீ", "366 ச.செ.மீ", "376 ச.செ.மீ", "386 ச.செ.மீ"]', N'மொத்தப் புறப்பரப்பு = 2(lb+bh+hl) = 2(80+48+60) = 376 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் மொத்தப் புறப்பரப்பு = 2(lb + bh + hl).', N'Area and Volume', N'EASY', 31),
    (@pracId, N'A rectangular field 70 m × 30 m has a path 3 m wide around it (outside). Find the area of the path.', N'["616 sq. m", "626 sq. m", "636 sq. m", "646 sq. m"]', 2, N'Outer = 76 × 36 = 2736 sq. m. Inner = 70 × 30 = 2100 sq. m. Path area = 2736 − 2100 = 636 sq. m. Key Learning Point: Compute outer and inner areas separately before subtracting.', N'70 மீ × 30 மீ அளவுள்ள ஒரு செவ்வக வயலைச் சுற்றி (வெளிப்புறமாக) 3 மீ அகலமுள்ள ஒரு பாதை உள்ளது. பாதையின் பரப்பளவைக் காண்க.', N'["616 ச.மீ", "626 ச.மீ", "636 ச.மீ", "646 ச.மீ"]', N'வெளி = 76 × 36 = 2736 ச.மீ. உள் = 70 × 30 = 2100 ச.மீ. பாதையின் பரப்பளவு = 2736 − 2100 = 636 ச.மீ. முக்கியக் கற்றல் கருத்து: கழிக்கும் முன் வெளி மற்றும் உள் பரப்பளவுகளைத் தனித்தனியாகக் கணக்கிடவும்.', N'Area and Volume', N'MEDIUM', 32),
    (@pracId, N'The circumference of a circular garden is 88 m. Find its area. (π = 22/7)', N'["596 sq. m", "606 sq. m", "616 sq. m", "626 sq. m"]', 2, N'2πr = 88 → r = 14 m. Area = 22/7 × 196 = 616 sq. m. Key Learning Point: Recover the radius from the circumference first, then apply the area formula.', N'ஒரு வட்ட வடிவத் தோட்டத்தின் சுற்றளவு 88 மீ. அதன் பரப்பளவைக் காண்க. (π = 22/7)', N'["596 ச.மீ", "606 ச.மீ", "616 ச.மீ", "626 ச.மீ"]', N'2πr = 88 → r = 14 மீ. பரப்பளவு = 22/7 × 196 = 616 ச.மீ. முக்கியக் கற்றல் கருத்து: முதலில் சுற்றளவிலிருந்து ஆரத்தைப் பெற்று, பின்னர் பரப்பளவுச் சூத்திரத்தைப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 33),
    (@pracId, N'A cylindrical tank has radius 14 m and height 5 m. Find its volume. (π = 22/7)', N'["3060 cubic m", "3070 cubic m", "3080 cubic m", "3090 cubic m"]', 2, N'Volume = 22/7 × 196 × 5 = 3080 cubic m. Key Learning Point: Volume of a cylinder = πr²h.', N'ஓர் உருளை வடிவத் தொட்டியின் ஆரம் 14 மீ, உயரம் 5 மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["3060 க.மீ", "3070 க.மீ", "3080 க.மீ", "3090 க.மீ"]', N'கன அளவு = 22/7 × 196 × 5 = 3080 க.மீ. முக்கியக் கற்றல் கருத்து: உருளையின் கன அளவு = πr²h.', N'Area and Volume', N'EASY', 34),
    (@pracId, N'Find the total surface area of a cube with edge 11 cm.', N'["706 sq. cm", "716 sq. cm", "726 sq. cm", "736 sq. cm"]', 2, N'TSA = 6 × 121 = 726 sq. cm. Key Learning Point: Total surface area of a cube = 6 × (edge)².', N'விளிம்பு 11 செ.மீ கொண்ட ஒரு கனசதுரத்தின் மொத்தப் புறப்பரப்பைக் காண்க.', N'["706 ச.செ.மீ", "716 ச.செ.மீ", "726 ச.செ.மீ", "736 ச.செ.மீ"]', N'மொத்தப் புறப்பரப்பு = 6 × 121 = 726 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் மொத்தப் புறப்பரப்பு = 6 × (விளிம்பு)².', N'Area and Volume', N'EASY', 35),
    (@pracId, N'A cone has radius 14 cm and slant height 25 cm. Find its curved surface area. (π = 22/7)', N'["1080 sq. cm", "1090 sq. cm", "1100 sq. cm", "1110 sq. cm"]', 2, N'CSA = 22/7 × 14 × 25 = 1100 sq. cm. Key Learning Point: CSA of a cone uses the slant height, not the vertical height.', N'ஒரு கூம்பின் ஆரம் 14 செ.மீ, சாய்வுயரம் 25 செ.மீ. அதன் வளைபரப்பைக் காண்க. (π = 22/7)', N'["1080 ச.செ.மீ", "1090 ச.செ.மீ", "1100 ச.செ.மீ", "1110 ச.செ.மீ"]', N'வளைபரப்பு = 22/7 × 14 × 25 = 1100 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் வளைபரப்புக்குச் செங்குத்து உயரம் அல்ல, சாய்வுயரம் பயன்படுத்தப்படுகிறது.', N'Area and Volume', N'EASY', 36),
    (@pracId, N'Two cubes, each of volume 27 cubic cm, are joined end to end. Find the surface area of the resulting cuboid.', N'["80 sq. cm", "85 sq. cm", "90 sq. cm", "95 sq. cm"]', 2, N'Side = 3 cm. Resulting cuboid = 6×3×3. SA = 2(18+9+18) = 90 sq. cm. Key Learning Point: Compute the resulting cuboid’s surface area directly, since the joined faces are no longer external.', N'ஒவ்வொன்றும் 27 க.செ.மீ கன அளவுள்ள இரண்டு கனசதுரங்கள் முனையோடு முனையாக இணைக்கப்படுகின்றன. விளையும் கனச்செவ்வகத்தின் புறப்பரப்பைக் காண்க.', N'["80 ச.செ.மீ", "85 ச.செ.மீ", "90 ச.செ.மீ", "95 ச.செ.மீ"]', N'பக்கம் = 3 செ.மீ. விளையும் கனச்செவ்வகம் = 6×3×3. புறப்பரப்பு = 2(18+9+18) = 90 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: இணைந்த முகங்கள் இனி வெளிப்புறமாக இல்லாததால், விளையும் கனச்செவ்வகத்தின் புறப்பரப்பை நேரடியாகக் கணக்கிடவும்.', N'Area and Volume', N'MEDIUM', 37),
    (@pracId, N'Find the volume of a sphere of radius 14 cm. (π = 22/7)', N'["11488⅔ cubic cm", "11498⅔ cubic cm", "11508⅔ cubic cm", "11518⅔ cubic cm"]', 1, N'Volume = 4/3 × 22/7 × 14³ = 4/3 × 22/7 × 2744 = 11498⅔ cubic cm. Key Learning Point: Volume of a sphere = 4/3πr³.', N'ஆரம் 14 செ.மீ கொண்ட ஒரு கோளத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["11488⅔ க.செ.மீ", "11498⅔ க.செ.மீ", "11508⅔ க.செ.மீ", "11518⅔ க.செ.மீ"]', N'கன அளவு = 4/3 × 22/7 × 14³ = 4/3 × 22/7 × 2744 = 11498⅔ க.செ.மீ. முக்கியக் கற்றல் கருத்து: கோளத்தின் கன அளவு = 4/3πr³.', N'Area and Volume', N'EASY', 38),
    (@pracId, N'A cylinder and a cone have equal radius (10 cm) and equal height (21 cm). Find the ratio of their volumes.', N'["1:3", "2:1", "3:1", "3:2"]', 2, N'Ratio = 3:1 (cylinder is always 3 times a cone of equal base and height). Key Learning Point: For equal radius and height, a cylinder’s volume is always three times a cone’s volume.', N'ஓர் உருளையும் ஒரு கூம்பும் சம ஆரமும் (10 செ.மீ) சம உயரமும் (21 செ.மீ) கொண்டவை. அவற்றின் கன அளவுகளின் விகிதத்தைக் காண்க.', N'["1:3", "2:1", "3:1", "3:2"]', N'விகிதம் = 3:1 (சம அடியும் சம உயரமும் கொண்ட கூம்பைவிட உருளை எப்போதும் 3 மடங்கு). முக்கியக் கற்றல் கருத்து: சம ஆரமும் சம உயரமும் கொண்டால், உருளையின் கன அளவு எப்போதும் கூம்பின் கன அளவின் மூன்று மடங்காகும்.', N'Area and Volume', N'EASY', 39),
    (@pracId, N'A rectangular sheet 88 cm × 25 cm is rolled along its length into a cylinder. Find the radius. (π = 22/7)', N'["12 cm", "13 cm", "14 cm", "15 cm"]', 2, N'2πr = 88 → r = 14 cm. Key Learning Point: The rolled side becomes the circumference of the cylinder’s base.', N'88 செ.மீ × 25 செ.மீ அளவுள்ள ஒரு செவ்வகத்தாள் அதன் நீளவாக்கில் சுருட்டப்பட்டு ஓர் உருளை ஆக்கப்படுகிறது. ஆரத்தைக் காண்க. (π = 22/7)', N'["12 செ.மீ", "13 செ.மீ", "14 செ.மீ", "15 செ.மீ"]', N'2πr = 88 → r = 14 செ.மீ. முக்கியக் கற்றல் கருத்து: சுருட்டப்பட்ட பக்கம் உருளையின் அடிச்சுற்றளவாகிறது.', N'Area and Volume', N'EASY', 40),
    (@pracId, N'A cube of edge 15 cm is melted into smaller cubes of edge 5 cm each. Find the number of smaller cubes.', N'["21", "24", "27", "30"]', 2, N'Number = 15³/5³ = 3375/125 = 27. Key Learning Point: Total volume is conserved – divide the original volume by the new unit’s volume.', N'விளிம்பு 15 செ.மீ கொண்ட ஒரு கனசதுரம் உருக்கப்பட்டு, ஒவ்வொன்றும் 5 செ.மீ விளிம்புடைய சிறிய கனசதுரங்களாக்கப்படுகிறது. சிறிய கனசதுரங்களின் எண்ணிக்கையைக் காண்க.', N'["21", "24", "27", "30"]', N'எண்ணிக்கை = 15³/5³ = 3375/125 = 27. முக்கியக் கற்றல் கருத்து: மொத்தக் கன அளவு மாறாது – மூலக் கன அளவைப் புதிய அலகின் கன அளவால் வகுக்கவும்.', N'Area and Volume', N'EASY', 41),
    (@pracId, N'The area of a trapezium is 456 sq. cm with parallel sides 27 cm and 21 cm. Find the height.', N'["17 cm", "18 cm", "19 cm", "20 cm"]', 2, N'456 = ½ × 48 × h = 24h → h = 19 cm. Key Learning Point: Area of a trapezium = ½ × (sum of parallel sides) × height.', N'ஒரு சரிவகத்தின் பரப்பளவு 456 ச.செ.மீ; அதன் இணைப்பக்கங்கள் 27 செ.மீ மற்றும் 21 செ.மீ. உயரத்தைக் காண்க.', N'["17 செ.மீ", "18 செ.மீ", "19 செ.மீ", "20 செ.மீ"]', N'456 = ½ × 48 × h = 24h → h = 19 செ.மீ. முக்கியக் கற்றல் கருத்து: சரிவகத்தின் பரப்பளவு = ½ × (இணைப்பக்கங்களின் கூடுதல்) × உயரம்.', N'Area and Volume', N'EASY', 42),
    (@pracId, N'A right circular cone has base radius 7 cm and height 6 cm. Find its volume. (π = 22/7)', N'["298 cubic cm", "308 cubic cm", "318 cubic cm", "328 cubic cm"]', 1, N'Volume = ⅓ × 22/7 × 49 × 6 = ⅓ × 22 × 7 × 6 = 308 cubic cm. Key Learning Point: Volume of a cone = ⅓πr²h – use the vertical height, not the slant height.', N'ஒரு நேர்வட்டக் கூம்பின் அடி ஆரம் 7 செ.மீ, உயரம் 6 செ.மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["298 க.செ.மீ", "308 க.செ.மீ", "318 க.செ.மீ", "328 க.செ.மீ"]', N'கன அளவு = ⅓ × 22/7 × 49 × 6 = ⅓ × 22 × 7 × 6 = 308 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் கன அளவு = ⅓πr²h – சாய்வுயரம் அல்ல, செங்குத்து உயரத்தைப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 43),
    (@pracId, N'A cylindrical pipe has internal radius 4 cm, external radius 6 cm, and length 21 cm. Find the volume of metal used. (π = 22/7)', N'["1300 cubic cm", "1310 cubic cm", "1320 cubic cm", "1330 cubic cm"]', 2, N'Volume = 22/7 × (36−16) × 21 = 22/7 × 20 × 21 = 1320 cubic cm. Key Learning Point: For a hollow cylinder, subtract the inner volume from the outer volume using R² − r².', N'ஓர் உருளை வடிவக் குழாயின் உள் ஆரம் 4 செ.மீ, வெளி ஆரம் 6 செ.மீ, நீளம் 21 செ.மீ. பயன்படுத்தப்பட்ட உலோகத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["1300 க.செ.மீ", "1310 க.செ.மீ", "1320 க.செ.மீ", "1330 க.செ.மீ"]', N'கன அளவு = 22/7 × (36−16) × 21 = 22/7 × 20 × 21 = 1320 க.செ.மீ. முக்கியக் கற்றல் கருத்து: உள்ளீடற்ற உருளைக்கு, R² − r² ஐப் பயன்படுத்தி வெளிக் கன அளவிலிருந்து உள் கன அளவைக் கழிக்கவும்.', N'Area and Volume', N'MEDIUM', 44),
    (@pracId, N'A room is 15 m long, 10 m wide, and 6 m high. Find the cost of whitewashing the walls and ceiling (excluding the floor) at ₹4 per sq. m.', N'["₹1700", "₹1750", "₹1800", "₹1850"]', 2, N'Wall area = 2×6×25 = 300 sq. m. Ceiling = 150 sq. m. Total = 450 sq. m. Cost = 450 × 4 = ₹1800. Key Learning Point: Identify exactly which surfaces are included before computing the total area.', N'ஓர் அறை 15 மீ நீளம், 10 மீ அகலம், 6 மீ உயரம் கொண்டது. ஒரு ச.மீ-க்கு ₹4 வீதம் சுவர்களுக்கும் மேற்கூரைக்கும் (தரை நீங்கலாக) வெள்ளையடிக்க ஆகும் செலவைக் காண்க.', N'["₹1700", "₹1750", "₹1800", "₹1850"]', N'சுவர்களின் பரப்பு = 2×6×25 = 300 ச.மீ. மேற்கூரை = 150 ச.மீ. மொத்தம் = 450 ச.மீ. செலவு = 450 × 4 = ₹1800. முக்கியக் கற்றல் கருத்து: மொத்தப் பரப்பைக் கணக்கிடும் முன் எந்தெந்தப் பரப்புகள் சேர்க்கப்பட்டுள்ளன என்பதைத் துல்லியமாக அடையாளம் காணவும்.', N'Area and Volume', N'MEDIUM', 45),
    (@pracId, N'A sphere of radius 9 cm is melted and recast into a cylinder of radius 3 cm. Find the height of the cylinder.', N'["98 cm", "100 cm", "104 cm", "108 cm"]', 3, N'Volume of sphere = 4/3π × 729 = 972π. Volume of cylinder = π×9×h = 9πh. 9h = 972 → h = 108 cm. Key Learning Point: Equate the volume of the original solid to the volume of the new solid, and solve for the unknown dimension.', N'ஆரம் 9 செ.மீ கொண்ட ஒரு கோளம் உருக்கப்பட்டு, ஆரம் 3 செ.மீ கொண்ட ஓர் உருளையாக மறுவார்க்கப்படுகிறது. உருளையின் உயரத்தைக் காண்க.', N'["98 செ.மீ", "100 செ.மீ", "104 செ.மீ", "108 செ.மீ"]', N'கோளத்தின் கன அளவு = 4/3π × 729 = 972π. உருளையின் கன அளவு = π×9×h = 9πh. 9h = 972 → h = 108 செ.மீ. முக்கியக் கற்றல் கருத்து: மூலத் திண்மத்தின் கன அளவைப் புதிய திண்மத்தின் கன அளவுடன் சமப்படுத்தி, தெரியாத அளவைக் காணவும்.', N'Area and Volume', N'MEDIUM', 46),
    (@pracId, N'The diagonal of a cube is 9√3 cm. Find its volume.', N'["719 cubic cm", "729 cubic cm", "739 cubic cm", "749 cubic cm"]', 1, N'Diagonal = a√3 → a = 9. Volume = 9³ = 729 cubic cm. Key Learning Point: The space diagonal of a cube equals side × √3.', N'ஒரு கனசதுரத்தின் மூலைவிட்டம் 9√3 செ.மீ. அதன் கன அளவைக் காண்க.', N'["719 க.செ.மீ", "729 க.செ.மீ", "739 க.செ.மீ", "749 க.செ.மீ"]', N'மூலைவிட்டம் = a√3 → a = 9. கன அளவு = 9³ = 729 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் வெளி மூலைவிட்டம் = பக்கம் × √3.', N'Area and Volume', N'EASY', 47),
    (@pracId, N'A well of diameter 28 m is dug 10 m deep. Earth is spread around it to form an embankment of width 7 m. Find the height of the embankment. (π = 22/7)', N'["6 m", "7 m", "8 m", "9 m"]', 2, N'Well: r=14, depth=10. Volume = 22/7 × 196 × 10 = 6160 cubic m. Embankment: inner radius 14, outer radius 21. Area = 22/7 × (441−196) = 770 sq. m. Height = 6160 ÷ 770 = 8 m. Key Learning Point: The volume of earth dug equals the volume of the embankment ring – set the two equal and solve.', N'28 மீ விட்டமுள்ள ஒரு கிணறு 10 மீ ஆழத்திற்குத் தோண்டப்படுகிறது. தோண்டிய மண் அதைச் சுற்றிப் பரப்பப்பட்டு 7 மீ அகலமுள்ள ஒரு கரை அமைக்கப்படுகிறது. கரையின் உயரத்தைக் காண்க. (π = 22/7)', N'["6 மீ", "7 மீ", "8 மீ", "9 மீ"]', N'கிணறு: r=14, ஆழம்=10. கன அளவு = 22/7 × 196 × 10 = 6160 க.மீ. கரை: உள் ஆரம் 14, வெளி ஆரம் 21. பரப்பு = 22/7 × (441−196) = 770 ச.மீ. உயரம் = 6160 ÷ 770 = 8 மீ. முக்கியக் கற்றல் கருத்து: தோண்டிய மண்ணின் கன அளவு கரை வளையத்தின் கன அளவுக்குச் சமம் – இரண்டையும் சமப்படுத்தித் தீர்க்கவும்.', N'Area and Volume', N'HARD', 48),
    (@pracId, N'The curved surface area of a cylinder is 1760 sq. cm and its height is 20 cm. Find the radius. (π = 22/7)', N'["12 cm", "13 cm", "14 cm", "15 cm"]', 2, N'CSA = 2πrh → 1760 = 2 × 22/7 × r × 20 → r = 1760 × 7/880 = 14 cm. Key Learning Point: When CSA and height are given, isolate the radius algebraically from the CSA formula.', N'ஓர் உருளையின் வளைபரப்பு 1760 ச.செ.மீ, உயரம் 20 செ.மீ. ஆரத்தைக் காண்க. (π = 22/7)', N'["12 செ.மீ", "13 செ.மீ", "14 செ.மீ", "15 செ.மீ"]', N'வளைபரப்பு = 2πrh → 1760 = 2 × 22/7 × r × 20 → r = 1760 × 7/880 = 14 செ.மீ. முக்கியக் கற்றல் கருத்து: வளைபரப்பும் உயரமும் கொடுக்கப்பட்டால், வளைபரப்புச் சூத்திரத்திலிருந்து ஆரத்தை இயற்கணித முறையில் தனிப்படுத்தவும்.', N'Area and Volume', N'MEDIUM', 49),
    (@pracId, N'A conical tent has radius 7 m and height 24 m. Find the fabric required (curved surface area). (π = 22/7)', N'["540 sq. m", "545 sq. m", "550 sq. m", "555 sq. m"]', 2, N'Slant height = √(49+576) = 25 m. CSA = 22/7 × 7 × 25 = 550 sq. m. Key Learning Point: For a cone, first find the slant height using the Pythagorean relationship (l² = r² + h²) if it is not directly given.', N'ஒரு கூம்பு வடிவக் கூடாரத்தின் ஆரம் 7 மீ, உயரம் 24 மீ. தேவையான துணியின் (வளைபரப்பு) அளவைக் காண்க. (π = 22/7)', N'["540 ச.மீ", "545 ச.மீ", "550 ச.மீ", "555 ச.மீ"]', N'சாய்வுயரம் = √(49+576) = 25 மீ. வளைபரப்பு = 22/7 × 7 × 25 = 550 ச.மீ. முக்கியக் கற்றல் கருத்து: கூம்புக்குச் சாய்வுயரம் நேரடியாகக் கொடுக்கப்படவில்லை எனில், பிதாகரஸ் தொடர்பைப் (l² = r² + h²) பயன்படுத்தி முதலில் அதைக் கண்டறியவும்.', N'Area and Volume', N'MEDIUM', 50),
    (@pracId, N'A rectangular tank measures 10 m × 8 m × 6 m. Find the maximum length of a rod that can be placed inside it (space diagonal).', N'["10√2 m", "12√2 m", "14√2 m", "16√2 m"]', 0, N'Diagonal = √(100+64+36) = √200 = 10√2 m (≈14.14 m). Key Learning Point: The space diagonal of a cuboid = √(l²+b²+h²).', N'ஒரு செவ்வகத் தொட்டி 10 மீ × 8 மீ × 6 மீ அளவுடையது. அதனுள் வைக்கக்கூடிய ஒரு கம்பியின் அதிகபட்ச நீளத்தை (வெளி மூலைவிட்டம்) காண்க.', N'["10√2 மீ", "12√2 மீ", "14√2 மீ", "16√2 மீ"]', N'மூலைவிட்டம் = √(100+64+36) = √200 = 10√2 மீ (≈14.14 மீ). முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் வெளி மூலைவிட்டம் = √(l²+b²+h²).', N'Area and Volume', N'MEDIUM', 51),
    (@pracId, N'The volume of a cube is 1728 cubic cm. Find its total surface area.', N'["844 sq. cm", "854 sq. cm", "864 sq. cm", "874 sq. cm"]', 2, N'Side = 12 cm (12³=1728). TSA = 6 × 144 = 864 sq. cm. Key Learning Point: When volume is given, first recover the side length by taking the cube root.', N'ஒரு கனசதுரத்தின் கன அளவு 1728 க.செ.மீ. அதன் மொத்தப் புறப்பரப்பைக் காண்க.', N'["844 ச.செ.மீ", "854 ச.செ.மீ", "864 ச.செ.மீ", "874 ச.செ.மீ"]', N'பக்கம் = 12 செ.மீ (12³=1728). மொத்தப் புறப்பரப்பு = 6 × 144 = 864 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கன அளவு கொடுக்கப்பட்டால், முதலில் கனமூலம் எடுத்துப் பக்க நீளத்தைப் பெறவும்.', N'Area and Volume', N'MEDIUM', 52),
    (@pracId, N'A sphere has surface area 616 sq. cm. Find its radius. (π = 22/7)', N'["5 cm", "6 cm", "7 cm", "8 cm"]', 2, N'4πr² = 616 → r² = 616 × 7/88 = 49 → r = 7 cm. Key Learning Point: When surface area is given, isolate r² algebraically, then take the square root.', N'ஒரு கோளத்தின் புறப்பரப்பு 616 ச.செ.மீ. அதன் ஆரத்தைக் காண்க. (π = 22/7)', N'["5 செ.மீ", "6 செ.மீ", "7 செ.மீ", "8 செ.மீ"]', N'4πr² = 616 → r² = 616 × 7/88 = 49 → r = 7 செ.மீ. முக்கியக் கற்றல் கருத்து: புறப்பரப்பு கொடுக்கப்பட்டால், r² ஐ இயற்கணித முறையில் தனிப்படுத்தி, பின்னர் வர்க்கமூலம் எடுக்கவும்.', N'Area and Volume', N'MEDIUM', 53),
    (@pracId, N'Two solid hemispheres of radius 7 cm each are placed together to form a sphere. Find the volume of the resulting sphere. (π = 22/7)', N'["1417⅓ cubic cm", "1427⅓ cubic cm", "1437⅓ cubic cm", "1447⅓ cubic cm"]', 2, N'Volume of sphere = 4/3 × 22/7 × 343 = 1437⅓ cubic cm. Key Learning Point: Two hemispheres of the same radius joined at their flat faces form a full sphere.', N'ஒவ்வொன்றும் 7 செ.மீ ஆரமுள்ள இரண்டு திண்ம அரைக்கோளங்கள் ஒன்றாக வைக்கப்பட்டு ஒரு கோளம் உருவாகிறது. விளையும் கோளத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["1417⅓ க.செ.மீ", "1427⅓ க.செ.மீ", "1437⅓ க.செ.மீ", "1447⅓ க.செ.மீ"]', N'கோளத்தின் கன அளவு = 4/3 × 22/7 × 343 = 1437⅓ க.செ.மீ. முக்கியக் கற்றல் கருத்து: ஒரே ஆரமுள்ள இரண்டு அரைக்கோளங்கள் அவற்றின் தட்டையான முகங்களில் இணைக்கப்பட்டால் முழுக்கோளம் உருவாகிறது.', N'Area and Volume', N'EASY', 54),
    (@pracId, N'A conical vessel of radius 6 cm and height 8 cm is full of water. The water is poured into a cylindrical vessel of radius 4 cm. Find the height of water in the cylinder.', N'["5 cm", "6 cm", "7 cm", "8 cm"]', 1, N'Volume of cone = ⅓π×36×8 = 96π. Volume of cylinder = π×16×h = 16πh. 16h = 96 → h = 6 cm. Key Learning Point: When liquid is transferred between containers, equate the volumes and solve for the unknown dimension.', N'ஆரம் 6 செ.மீ, உயரம் 8 செ.மீ கொண்ட ஒரு கூம்பு வடிவப் பாத்திரம் முழுவதும் நீர் நிரம்பியுள்ளது. அந்நீர் ஆரம் 4 செ.மீ கொண்ட ஓர் உருளை வடிவப் பாத்திரத்தில் ஊற்றப்படுகிறது. உருளையில் நீரின் உயரத்தைக் காண்க.', N'["5 செ.மீ", "6 செ.மீ", "7 செ.மீ", "8 செ.மீ"]', N'கூம்பின் கன அளவு = ⅓π×36×8 = 96π. உருளையின் கன அளவு = π×16×h = 16πh. 16h = 96 → h = 6 செ.மீ. முக்கியக் கற்றல் கருத்து: ஒரு பாத்திரத்திலிருந்து மற்றொன்றுக்குத் திரவம் மாற்றப்படும்போது, கன அளவுகளைச் சமப்படுத்தித் தெரியாத அளவைக் காணவும்.', N'Area and Volume', N'MEDIUM', 55);
INSERT INTO dbo.Questions (AssessmentId, QuestionText, OptionsJson, CorrectIndex, Explanation, QuestionTextTa, OptionsJsonTa, ExplanationTa, Topic, Difficulty, OrderIndex)
VALUES
    (@gradId, N'Find the area of a rectangle with length 20 m and breadth 14 m.', N'["260 sq. m", "270 sq. m", "280 sq. m", "290 sq. m"]', 2, N'Area = 20 × 14 = 280 sq. m. Key Learning Point: Area of a rectangle = length × breadth.', N'நீளம் 20 மீ, அகலம் 14 மீ கொண்ட ஒரு செவ்வகத்தின் பரப்பளவைக் காண்க.', N'["260 ச.மீ", "270 ச.மீ", "280 ச.மீ", "290 ச.மீ"]', N'பரப்பளவு = 20 × 14 = 280 ச.மீ. முக்கியக் கற்றல் கருத்து: செவ்வகத்தின் பரப்பளவு = நீளம் × அகலம்.', N'Area and Volume', N'EASY', 1),
    (@gradId, N'Find the area of a square with side 18 cm.', N'["314 sq. cm", "324 sq. cm", "334 sq. cm", "344 sq. cm"]', 1, N'Area = 18² = 324 sq. cm. Key Learning Point: Area of a square = side².', N'பக்கம் 18 செ.மீ கொண்ட ஒரு சதுரத்தின் பரப்பளவைக் காண்க.', N'["314 ச.செ.மீ", "324 ச.செ.மீ", "334 ச.செ.மீ", "344 ச.செ.மீ"]', N'பரப்பளவு = 18² = 324 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: சதுரத்தின் பரப்பளவு = பக்கம்².', N'Area and Volume', N'EASY', 2),
    (@gradId, N'Find the volume of a cube with side 7 cm.', N'["323 cubic cm", "333 cubic cm", "343 cubic cm", "353 cubic cm"]', 2, N'Volume = 7³ = 343 cubic cm. Key Learning Point: Volume of a cube = side³.', N'பக்கம் 7 செ.மீ கொண்ட ஒரு கனசதுரத்தின் கன அளவைக் காண்க.', N'["323 க.செ.மீ", "333 க.செ.மீ", "343 க.செ.மீ", "353 க.செ.மீ"]', N'கன அளவு = 7³ = 343 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் கன அளவு = பக்கம்³.', N'Area and Volume', N'EASY', 3),
    (@gradId, N'Find the area of a circle with radius 21 cm. (π = 22/7)', N'["1366 sq. cm", "1376 sq. cm", "1386 sq. cm", "1396 sq. cm"]', 2, N'Area = 22/7 × 21² = 22/7 × 441 = 1386 sq. cm. Key Learning Point: Area of a circle = πr²; use π = 22/7 when the radius is a multiple of 7.', N'ஆரம் 21 செ.மீ கொண்ட ஒரு வட்டத்தின் பரப்பளவைக் காண்க. (π = 22/7)', N'["1366 ச.செ.மீ", "1376 ச.செ.மீ", "1386 ச.செ.மீ", "1396 ச.செ.மீ"]', N'பரப்பளவு = 22/7 × 21² = 22/7 × 441 = 1386 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: வட்டத்தின் பரப்பளவு = πr²; ஆரம் 7-இன் மடங்காக இருக்கும்போது π = 22/7 ஐப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 4),
    (@gradId, N'Find the volume of a cuboid 15 cm × 8 cm × 6 cm.', N'["700 cubic cm", "710 cubic cm", "720 cubic cm", "730 cubic cm"]', 2, N'Volume = 15 × 8 × 6 = 720 cubic cm. Key Learning Point: Volume of a cuboid = length × breadth × height.', N'15 செ.மீ × 8 செ.மீ × 6 செ.மீ அளவுள்ள ஒரு கனச்செவ்வகத்தின் கன அளவைக் காண்க.', N'["700 க.செ.மீ", "710 க.செ.மீ", "720 க.செ.மீ", "730 க.செ.மீ"]', N'கன அளவு = 15 × 8 × 6 = 720 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் கன அளவு = நீளம் × அகலம் × உயரம்.', N'Area and Volume', N'EASY', 5),
    (@gradId, N'Find the total surface area of a cuboid 12 cm × 9 cm × 7 cm.', N'["490 sq. cm", "500 sq. cm", "510 sq. cm", "520 sq. cm"]', 2, N'TSA = 2(lb + bh + hl) = 2(12×9 + 9×7 + 7×12) = 2(108 + 63 + 84) = 2 × 255 = 510 sq. cm. Key Learning Point: Total surface area of a cuboid = 2(lb + bh + hl).', N'12 செ.மீ × 9 செ.மீ × 7 செ.மீ அளவுள்ள ஒரு கனச்செவ்வகத்தின் மொத்தப் புறப்பரப்பைக் காண்க.', N'["490 ச.செ.மீ", "500 ச.செ.மீ", "510 ச.செ.மீ", "520 ச.செ.மீ"]', N'மொத்தப் புறப்பரப்பு = 2(lb + bh + hl) = 2(12×9 + 9×7 + 7×12) = 2(108 + 63 + 84) = 2 × 255 = 510 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கனச்செவ்வகத்தின் மொத்தப் புறப்பரப்பு = 2(lb + bh + hl).', N'Area and Volume', N'EASY', 6),
    (@gradId, N'A rectangular field 50 m × 30 m has a path 2.5 m wide around it (outside). Find the area of the path.', N'["405 sq. m", "415 sq. m", "425 sq. m", "435 sq. m"]', 2, N'Outer dimensions = (50 + 2×2.5) × (30 + 2×2.5) = 55 × 35 = 1925 sq. m. Inner area = 50 × 30 = 1500 sq. m. Path area = 1925 − 1500 = 425 sq. m. Key Learning Point: A path of width w outside adds 2w to each dimension; compute the outer and inner areas separately, then subtract.', N'50 மீ × 30 மீ அளவுள்ள ஒரு செவ்வக வயலைச் சுற்றி (வெளிப்புறமாக) 2.5 மீ அகலமுள்ள ஒரு பாதை உள்ளது. பாதையின் பரப்பளவைக் காண்க.', N'["405 ச.மீ", "415 ச.மீ", "425 ச.மீ", "435 ச.மீ"]', N'வெளி அளவுகள் = (50 + 2×2.5) × (30 + 2×2.5) = 55 × 35 = 1925 ச.மீ. உள்பரப்பளவு = 50 × 30 = 1500 ச.மீ. பாதையின் பரப்பளவு = 1925 − 1500 = 425 ச.மீ. முக்கியக் கற்றல் கருத்து: வெளிப்புறமாக w அகலமுள்ள பாதை ஒவ்வோர் அளவுடனும் 2w ஐக் கூட்டுகிறது; வெளி மற்றும் உள்பரப்பளவுகளைத் தனித்தனியாகக் கணக்கிட்டுக் கழிக்கவும்.', N'Area and Volume', N'MEDIUM', 7),
    (@gradId, N'The circumference of a circular garden is 132 m. Find its area. (π = 22/7)', N'["1366 sq. m", "1376 sq. m", "1386 sq. m", "1396 sq. m"]', 2, N'2πr = 132 → r = 132 × 7/(2 × 22) = 21 m. Area = 22/7 × 21² = 22/7 × 441 = 1386 sq. m. Key Learning Point: Find the radius from the circumference first, then apply the area formula.', N'ஒரு வட்ட வடிவத் தோட்டத்தின் சுற்றளவு 132 மீ. அதன் பரப்பளவைக் காண்க. (π = 22/7)', N'["1366 ச.மீ", "1376 ச.மீ", "1386 ச.மீ", "1396 ச.மீ"]', N'2πr = 132 → r = 132 × 7/(2 × 22) = 21 மீ. பரப்பளவு = 22/7 × 21² = 22/7 × 441 = 1386 ச.மீ. முக்கியக் கற்றல் கருத்து: முதலில் சுற்றளவிலிருந்து ஆரத்தைக் கண்டறிந்து, பின்னர் பரப்பளவுச் சூத்திரத்தைப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 8),
    (@gradId, N'A cylindrical tank has radius 21 m and height 4 m. Find its volume. (π = 22/7)', N'["5524 cubic m", "5534 cubic m", "5544 cubic m", "5554 cubic m"]', 2, N'Volume = πr²h = 22/7 × 21² × 4 = 22/7 × 441 × 4 = 1386 × 4 = 5544 cubic m. Key Learning Point: Volume of a cylinder = πr²h.', N'ஓர் உருளை வடிவத் தொட்டியின் ஆரம் 21 மீ, உயரம் 4 மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["5524 க.மீ", "5534 க.மீ", "5544 க.மீ", "5554 க.மீ"]', N'கன அளவு = πr²h = 22/7 × 21² × 4 = 22/7 × 441 × 4 = 1386 × 4 = 5544 க.மீ. முக்கியக் கற்றல் கருத்து: உருளையின் கன அளவு = πr²h.', N'Area and Volume', N'EASY', 9),
    (@gradId, N'Find the total surface area of a cube with edge 13 cm.', N'["994 sq. cm", "1004 sq. cm", "1014 sq. cm", "1024 sq. cm"]', 2, N'TSA = 6a² = 6 × 13² = 6 × 169 = 1014 sq. cm. Key Learning Point: Total surface area of a cube = 6 × (edge)².', N'விளிம்பு 13 செ.மீ கொண்ட ஒரு கனசதுரத்தின் மொத்தப் புறப்பரப்பைக் காண்க.', N'["994 ச.செ.மீ", "1004 ச.செ.மீ", "1014 ச.செ.மீ", "1024 ச.செ.மீ"]', N'மொத்தப் புறப்பரப்பு = 6a² = 6 × 13² = 6 × 169 = 1014 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் மொத்தப் புறப்பரப்பு = 6 × (விளிம்பு)².', N'Area and Volume', N'EASY', 10),
    (@gradId, N'A cone has radius 21 cm and slant height 25 cm. Find its curved surface area. (π = 22/7)', N'["1630 sq. cm", "1640 sq. cm", "1650 sq. cm", "1660 sq. cm"]', 2, N'CSA = πrl = 22/7 × 21 × 25 = 66 × 25 = 1650 sq. cm. Key Learning Point: Curved surface area of a cone = πrl, where l is the slant height.', N'ஒரு கூம்பின் ஆரம் 21 செ.மீ, சாய்வுயரம் 25 செ.மீ. அதன் வளைபரப்பைக் காண்க. (π = 22/7)', N'["1630 ச.செ.மீ", "1640 ச.செ.மீ", "1650 ச.செ.மீ", "1660 ச.செ.மீ"]', N'வளைபரப்பு = πrl = 22/7 × 21 × 25 = 66 × 25 = 1650 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் வளைபரப்பு = πrl; இங்கு l என்பது சாய்வுயரம்.', N'Area and Volume', N'EASY', 11),
    (@gradId, N'Two cubes, each of volume 125 cubic cm, are joined end to end. Find the surface area of the resulting cuboid.', N'["230 sq. cm", "240 sq. cm", "250 sq. cm", "260 sq. cm"]', 2, N'Side of each cube = 5 cm (since 5³ = 125). Resulting cuboid = 10 × 5 × 5. SA = 2(10×5 + 5×5 + 5×10) = 2(50 + 25 + 50) = 250 sq. cm. Key Learning Point: When two cubes are joined, the joined faces disappear — compute the resulting cuboid''s surface area directly.', N'ஒவ்வொன்றும் 125 க.செ.மீ கன அளவுள்ள இரண்டு கனசதுரங்கள் முனையோடு முனையாக இணைக்கப்படுகின்றன. விளையும் கனச்செவ்வகத்தின் புறப்பரப்பைக் காண்க.', N'["230 ச.செ.மீ", "240 ச.செ.மீ", "250 ச.செ.மீ", "260 ச.செ.மீ"]', N'ஒவ்வொரு கனசதுரத்தின் பக்கம் = 5 செ.மீ (5³ = 125 என்பதால்). விளையும் கனச்செவ்வகம் = 10 × 5 × 5. புறப்பரப்பு = 2(10×5 + 5×5 + 5×10) = 2(50 + 25 + 50) = 250 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: இரண்டு கனசதுரங்கள் இணைக்கப்படும்போது இணைந்த முகங்கள் மறைகின்றன — விளையும் கனச்செவ்வகத்தின் புறப்பரப்பை நேரடியாகக் கணக்கிடவும்.', N'Area and Volume', N'MEDIUM', 12),
    (@gradId, N'Find the volume of a sphere of radius 7 cm. (π = 22/7)', N'["1417⅓ cubic cm", "1427⅓ cubic cm", "1437⅓ cubic cm", "1447⅓ cubic cm"]', 2, N'Volume = 4/3 × 22/7 × 7³ = 4/3 × 22/7 × 343 = 4/3 × 1078 = 4312/3 = 1437⅓ cubic cm. Key Learning Point: Volume of a sphere = 4/3πr³.', N'ஆரம் 7 செ.மீ கொண்ட ஒரு கோளத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["1417⅓ க.செ.மீ", "1427⅓ க.செ.மீ", "1437⅓ க.செ.மீ", "1447⅓ க.செ.மீ"]', N'கன அளவு = 4/3 × 22/7 × 7³ = 4/3 × 22/7 × 343 = 4/3 × 1078 = 4312/3 = 1437⅓ க.செ.மீ. முக்கியக் கற்றல் கருத்து: கோளத்தின் கன அளவு = 4/3πr³.', N'Area and Volume', N'EASY', 13),
    (@gradId, N'A cylinder and a cone have equal radius (12 cm) and equal height (25 cm). Find the ratio of their volumes.', N'["1:3", "2:1", "3:1", "3:2"]', 2, N'Cylinder volume = πr²h. Cone volume = ⅓πr²h. Ratio = πr²h : ⅓πr²h = 3 : 1. Key Learning Point: For equal radius and height, a cylinder''s volume is always three times a cone''s volume, whatever the actual measurements.', N'ஓர் உருளையும் ஒரு கூம்பும் சம ஆரமும் (12 செ.மீ) சம உயரமும் (25 செ.மீ) கொண்டவை. அவற்றின் கன அளவுகளின் விகிதத்தைக் காண்க.', N'["1:3", "2:1", "3:1", "3:2"]', N'உருளையின் கன அளவு = πr²h. கூம்பின் கன அளவு = ⅓πr²h. விகிதம் = πr²h : ⅓πr²h = 3 : 1. முக்கியக் கற்றல் கருத்து: சம ஆரமும் சம உயரமும் கொண்டால், உண்மையான அளவுகள் எவையாக இருந்தாலும், உருளையின் கன அளவு எப்போதும் கூம்பின் கன அளவின் மூன்று மடங்காகும்.', N'Area and Volume', N'EASY', 14),
    (@gradId, N'A rectangular sheet 132 cm × 30 cm is rolled along its length into a cylinder. Find the radius. (π = 22/7)', N'["19 cm", "20 cm", "21 cm", "22 cm"]', 2, N'The 132 cm side becomes the circumference: 2πr = 132 → r = 132 × 7/(2 × 22) = 21 cm. Key Learning Point: When a sheet is rolled, the rolled side becomes the circumference of the base; the other side becomes the height.', N'132 செ.மீ × 30 செ.மீ அளவுள்ள ஒரு செவ்வகத்தாள் அதன் நீளவாக்கில் சுருட்டப்பட்டு ஓர் உருளை ஆக்கப்படுகிறது. ஆரத்தைக் காண்க. (π = 22/7)', N'["19 செ.மீ", "20 செ.மீ", "21 செ.மீ", "22 செ.மீ"]', N'132 செ.மீ பக்கம் அடிச்சுற்றளவாகிறது: 2πr = 132 → r = 132 × 7/(2 × 22) = 21 செ.மீ. முக்கியக் கற்றல் கருத்து: ஒரு தாள் சுருட்டப்படும்போது, சுருட்டப்பட்ட பக்கம் அடிச்சுற்றளவாகிறது; மற்றொரு பக்கம் உயரமாகிறது.', N'Area and Volume', N'EASY', 15),
    (@gradId, N'A cube of edge 20 cm is melted into smaller cubes of edge 4 cm each. Find the number of smaller cubes.', N'["105", "115", "125", "135"]', 2, N'Number of smaller cubes = 20³ / 4³ = 8000 / 64 = 125. Key Learning Point: In melting-and-recasting, total volume is conserved — divide the original volume by the volume of one new cube.', N'விளிம்பு 20 செ.மீ கொண்ட ஒரு கனசதுரம் உருக்கப்பட்டு, ஒவ்வொன்றும் 4 செ.மீ விளிம்புடைய சிறிய கனசதுரங்களாக்கப்படுகிறது. சிறிய கனசதுரங்களின் எண்ணிக்கையைக் காண்க.', N'["105", "115", "125", "135"]', N'சிறிய கனசதுரங்களின் எண்ணிக்கை = 20³ / 4³ = 8000 / 64 = 125. முக்கியக் கற்றல் கருத்து: உருக்கி மறுவார்ப்பில் மொத்தக் கன அளவு மாறாது — மூலக் கன அளவை ஒரு புதிய கனசதுரத்தின் கன அளவால் வகுக்கவும்.', N'Area and Volume', N'EASY', 16),
    (@gradId, N'The area of a trapezium is 200 sq. cm with parallel sides 18 cm and 14 cm. Find the height.', N'["11.5 cm", "12 cm", "12.5 cm", "13 cm"]', 2, N'Area = ½ × (a + b) × h → 200 = ½ × (18 + 14) × h → 200 = 16h → h = 12.5 cm. Key Learning Point: Area of a trapezium = ½ × (sum of parallel sides) × height.', N'ஒரு சரிவகத்தின் பரப்பளவு 200 ச.செ.மீ; அதன் இணைப்பக்கங்கள் 18 செ.மீ மற்றும் 14 செ.மீ. உயரத்தைக் காண்க.', N'["11.5 செ.மீ", "12 செ.மீ", "12.5 செ.மீ", "13 செ.மீ"]', N'பரப்பளவு = ½ × (a + b) × h → 200 = ½ × (18 + 14) × h → 200 = 16h → h = 12.5 செ.மீ. முக்கியக் கற்றல் கருத்து: சரிவகத்தின் பரப்பளவு = ½ × (இணைப்பக்கங்களின் கூடுதல்) × உயரம்.', N'Area and Volume', N'EASY', 17),
    (@gradId, N'A right circular cone has base radius 7 cm and height 9 cm. Find its volume. (π = 22/7)', N'["442 cubic cm", "452 cubic cm", "462 cubic cm", "472 cubic cm"]', 2, N'Volume = ⅓ × 22/7 × 7² × 9 = ⅓ × 154 × 9 = 462 cubic cm. Key Learning Point: Volume of a cone = ⅓πr²h — use the vertical height.', N'ஒரு நேர்வட்டக் கூம்பின் அடி ஆரம் 7 செ.மீ, உயரம் 9 செ.மீ. அதன் கன அளவைக் காண்க. (π = 22/7)', N'["442 க.செ.மீ", "452 க.செ.மீ", "462 க.செ.மீ", "472 க.செ.மீ"]', N'கன அளவு = ⅓ × 22/7 × 7² × 9 = ⅓ × 154 × 9 = 462 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கூம்பின் கன அளவு = ⅓πr²h — செங்குத்து உயரத்தைப் பயன்படுத்தவும்.', N'Area and Volume', N'EASY', 18),
    (@gradId, N'A cylindrical pipe has internal radius 5 cm, external radius 7 cm, and length 7 cm. Find the volume of metal used. (π = 22/7)', N'["508 cubic cm", "518 cubic cm", "528 cubic cm", "538 cubic cm"]', 2, N'Volume of metal = π(R² − r²)h = 22/7 × (49 − 25) × 7 = 22 × 24 = 528 cubic cm. Key Learning Point: For a hollow cylinder, volume of material = π(R² − r²)h.', N'ஓர் உருளை வடிவக் குழாயின் உள் ஆரம் 5 செ.மீ, வெளி ஆரம் 7 செ.மீ, நீளம் 7 செ.மீ. பயன்படுத்தப்பட்ட உலோகத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["508 க.செ.மீ", "518 க.செ.மீ", "528 க.செ.மீ", "538 க.செ.மீ"]', N'உலோகத்தின் கன அளவு = π(R² − r²)h = 22/7 × (49 − 25) × 7 = 22 × 24 = 528 க.செ.மீ. முக்கியக் கற்றல் கருத்து: உள்ளீடற்ற உருளைக்கு, பொருளின் கன அளவு = π(R² − r²)h.', N'Area and Volume', N'MEDIUM', 19),
    (@gradId, N'A room is 14 m long, 10 m wide, and 5 m high. Find the cost of whitewashing the walls and ceiling (excluding the floor) at ₹6 per sq. m.', N'["₹2160", "₹2220", "₹2280", "₹2340"]', 2, N'Wall area = 2h(l + b) = 2 × 5 × (14 + 10) = 240 sq. m. Ceiling area = 14 × 10 = 140 sq. m. Total = 380 sq. m. Cost = 380 × 6 = ₹2280. Key Learning Point: Identify exactly which surfaces are to be whitewashed (walls, ceiling, floor) before computing the total area.', N'ஓர் அறை 14 மீ நீளம், 10 மீ அகலம், 5 மீ உயரம் கொண்டது. ஒரு ச.மீ-க்கு ₹6 வீதம் சுவர்களுக்கும் மேற்கூரைக்கும் (தரை நீங்கலாக) வெள்ளையடிக்க ஆகும் செலவைக் காண்க.', N'["₹2160", "₹2220", "₹2280", "₹2340"]', N'சுவர்களின் பரப்பு = 2h(l + b) = 2 × 5 × (14 + 10) = 240 ச.மீ. மேற்கூரையின் பரப்பு = 14 × 10 = 140 ச.மீ. மொத்தம் = 380 ச.மீ. செலவு = 380 × 6 = ₹2280. முக்கியக் கற்றல் கருத்து: மொத்தப் பரப்பைக் கணக்கிடும் முன், வெள்ளையடிக்க வேண்டிய பரப்புகள் (சுவர்கள், மேற்கூரை, தரை) எவை என்பதைத் துல்லியமாக அடையாளம் காணவும்.', N'Area and Volume', N'MEDIUM', 20),
    (@gradId, N'A sphere of radius 12 cm is melted and recast into a cylinder of radius 6 cm. Find the height of the cylinder.', N'["58 cm", "61 cm", "64 cm", "67 cm"]', 2, N'Volume of sphere = 4/3 × π × 12³ = 4/3 × π × 1728 = 2304π. Volume of cylinder = π × 6² × h = 36πh. 36h = 2304 → h = 64 cm. Key Learning Point: Equate the volume of the original solid to that of the new solid; π cancels out.', N'ஆரம் 12 செ.மீ கொண்ட ஒரு கோளம் உருக்கப்பட்டு, ஆரம் 6 செ.மீ கொண்ட ஓர் உருளையாக மறுவார்க்கப்படுகிறது. உருளையின் உயரத்தைக் காண்க.', N'["58 செ.மீ", "61 செ.மீ", "64 செ.மீ", "67 செ.மீ"]', N'கோளத்தின் கன அளவு = 4/3 × π × 12³ = 4/3 × π × 1728 = 2304π. உருளையின் கன அளவு = π × 6² × h = 36πh. 36h = 2304 → h = 64 செ.மீ. முக்கியக் கற்றல் கருத்து: மூலத் திண்மத்தின் கன அளவைப் புதிய திண்மத்தின் கன அளவுடன் சமப்படுத்தவும்; π நீங்கிவிடும்.', N'Area and Volume', N'MEDIUM', 21),
    (@gradId, N'The diagonal of a cube is 15√3 cm. Find its volume.', N'["3325 cubic cm", "3350 cubic cm", "3375 cubic cm", "3400 cubic cm"]', 2, N'Diagonal = a√3 → 15√3 = a√3 → a = 15 cm. Volume = 15³ = 3375 cubic cm. Key Learning Point: The space diagonal of a cube = side × √3; recover the side first.', N'ஒரு கனசதுரத்தின் மூலைவிட்டம் 15√3 செ.மீ. அதன் கன அளவைக் காண்க.', N'["3325 க.செ.மீ", "3350 க.செ.மீ", "3375 க.செ.மீ", "3400 க.செ.மீ"]', N'மூலைவிட்டம் = a√3 → 15√3 = a√3 → a = 15 செ.மீ. கன அளவு = 15³ = 3375 க.செ.மீ. முக்கியக் கற்றல் கருத்து: கனசதுரத்தின் வெளி மூலைவிட்டம் = பக்கம் × √3; முதலில் பக்கத்தைக் கண்டறியவும்.', N'Area and Volume', N'MEDIUM', 22),
    (@gradId, N'A well of diameter 14 m is dug 9 m deep. Earth is spread around it to form an embankment of width 7 m. Find the height of the embankment. (π = 22/7)', N'["2 m", "2.5 m", "3 m", "3.5 m"]', 2, N'Well: r = 7 m, depth = 9 m. Volume of earth = 22/7 × 49 × 9 = 1386 cubic m. Embankment: inner radius 7 m, outer radius 7 + 7 = 14 m. Area = 22/7 × (14² − 7²) = 22/7 × 147 = 462 sq. m. Height = 1386 ÷ 462 = 3 m. Key Learning Point: Volume of earth dug out = volume of the embankment ring (ring area × height).', N'14 மீ விட்டமுள்ள ஒரு கிணறு 9 மீ ஆழத்திற்குத் தோண்டப்படுகிறது. தோண்டிய மண் அதைச் சுற்றிப் பரப்பப்பட்டு 7 மீ அகலமுள்ள ஒரு கரை அமைக்கப்படுகிறது. கரையின் உயரத்தைக் காண்க. (π = 22/7)', N'["2 மீ", "2.5 மீ", "3 மீ", "3.5 மீ"]', N'கிணறு: r = 7 மீ, ஆழம் = 9 மீ. மண்ணின் கன அளவு = 22/7 × 49 × 9 = 1386 க.மீ. கரை: உள் ஆரம் 7 மீ, வெளி ஆரம் 7 + 7 = 14 மீ. பரப்பு = 22/7 × (14² − 7²) = 22/7 × 147 = 462 ச.மீ. உயரம் = 1386 ÷ 462 = 3 மீ. முக்கியக் கற்றல் கருத்து: தோண்டிய மண்ணின் கன அளவு = கரை வளையத்தின் கன அளவு (வளையப் பரப்பு × உயரம்).', N'Area and Volume', N'HARD', 23),
    (@gradId, N'The curved surface area of a cylinder is 2200 sq. cm and its height is 25 cm. Find the radius. (π = 22/7)', N'["12 cm", "13 cm", "14 cm", "15 cm"]', 2, N'CSA = 2πrh → 2200 = 2 × 22/7 × r × 25 → 2200 = (1100/7) × r → r = 2200 × 7/1100 = 14 cm. Key Learning Point: When CSA and height are given, isolate the radius algebraically from CSA = 2πrh.', N'ஓர் உருளையின் வளைபரப்பு 2200 ச.செ.மீ, உயரம் 25 செ.மீ. ஆரத்தைக் காண்க. (π = 22/7)', N'["12 செ.மீ", "13 செ.மீ", "14 செ.மீ", "15 செ.மீ"]', N'வளைபரப்பு = 2πrh → 2200 = 2 × 22/7 × r × 25 → 2200 = (1100/7) × r → r = 2200 × 7/1100 = 14 செ.மீ. முக்கியக் கற்றல் கருத்து: வளைபரப்பும் உயரமும் கொடுக்கப்பட்டால், வளைபரப்பு = 2πrh என்பதிலிருந்து ஆரத்தை இயற்கணித முறையில் தனிப்படுத்தவும்.', N'Area and Volume', N'MEDIUM', 24),
    (@gradId, N'A conical tent has radius 14 m and height 48 m. Find the fabric required (curved surface area). (π = 22/7)', N'["2100 sq. m", "2150 sq. m", "2200 sq. m", "2250 sq. m"]', 2, N'Slant height l = √(r² + h²) = √(14² + 48²) = √(196 + 2304) = √2500 = 50 m. CSA = πrl = 22/7 × 14 × 50 = 2200 sq. m. Key Learning Point: Find the slant height using l² = r² + h² before calculating the curved surface area.', N'ஒரு கூம்பு வடிவக் கூடாரத்தின் ஆரம் 14 மீ, உயரம் 48 மீ. தேவையான துணியின் (வளைபரப்பு) அளவைக் காண்க. (π = 22/7)', N'["2100 ச.மீ", "2150 ச.மீ", "2200 ச.மீ", "2250 ச.மீ"]', N'சாய்வுயரம் l = √(r² + h²) = √(14² + 48²) = √(196 + 2304) = √2500 = 50 மீ. வளைபரப்பு = πrl = 22/7 × 14 × 50 = 2200 ச.மீ. முக்கியக் கற்றல் கருத்து: வளைபரப்பைக் கணக்கிடும் முன், l² = r² + h² ஐப் பயன்படுத்திச் சாய்வுயரத்தைக் கண்டறியவும்.', N'Area and Volume', N'MEDIUM', 25),
    (@gradId, N'A rectangular tank measures 12 m × 9 m × 8 m. Find the maximum length of a rod that can be placed inside it (space diagonal).', N'["15 m", "16 m", "17 m", "18 m"]', 2, N'Diagonal = √(l² + b² + h²) = √(12² + 9² + 8²) = √(144 + 81 + 64) = √289 = 17 m. Key Learning Point: The longest rod that fits in a cuboid = its space diagonal √(l² + b² + h²).', N'ஒரு செவ்வகத் தொட்டி 12 மீ × 9 மீ × 8 மீ அளவுடையது. அதனுள் வைக்கக்கூடிய ஒரு கம்பியின் அதிகபட்ச நீளத்தை (வெளி மூலைவிட்டம்) காண்க.', N'["15 மீ", "16 மீ", "17 மீ", "18 மீ"]', N'மூலைவிட்டம் = √(l² + b² + h²) = √(12² + 9² + 8²) = √(144 + 81 + 64) = √289 = 17 மீ. முக்கியக் கற்றல் கருத்து: ஒரு கனச்செவ்வகத்தில் பொருந்தும் மிக நீளமான கம்பி = அதன் வெளி மூலைவிட்டம் √(l² + b² + h²).', N'Area and Volume', N'MEDIUM', 26),
    (@gradId, N'The volume of a cube is 2744 cubic cm. Find its total surface area.', N'["1146 sq. cm", "1156 sq. cm", "1166 sq. cm", "1176 sq. cm"]', 3, N'Side = cube root of 2744 = 14 cm (since 14³ = 14 × 14 × 14 = 2744). TSA = 6 × 14² = 6 × 196 = 1176 sq. cm. Key Learning Point: When volume is given, first take the cube root to recover the side length.', N'ஒரு கனசதுரத்தின் கன அளவு 2744 க.செ.மீ. அதன் மொத்தப் புறப்பரப்பைக் காண்க.', N'["1146 ச.செ.மீ", "1156 ச.செ.மீ", "1166 ச.செ.மீ", "1176 ச.செ.மீ"]', N'பக்கம் = 2744-இன் கனமூலம் = 14 செ.மீ (14³ = 14 × 14 × 14 = 2744 என்பதால்). மொத்தப் புறப்பரப்பு = 6 × 14² = 6 × 196 = 1176 ச.செ.மீ. முக்கியக் கற்றல் கருத்து: கன அளவு கொடுக்கப்பட்டால், முதலில் கனமூலம் எடுத்துப் பக்க நீளத்தைப் பெறவும்.', N'Area and Volume', N'MEDIUM', 27),
    (@gradId, N'A sphere has surface area 2464 sq. cm. Find its radius. (π = 22/7)', N'["12 cm", "13 cm", "14 cm", "15 cm"]', 2, N'4πr² = 2464 → 4 × 22/7 × r² = 2464 → r² = 2464 × 7/88 = 196 → r = 14 cm. Key Learning Point: Surface area of a sphere = 4πr²; isolate r², then take the square root.', N'ஒரு கோளத்தின் புறப்பரப்பு 2464 ச.செ.மீ. அதன் ஆரத்தைக் காண்க. (π = 22/7)', N'["12 செ.மீ", "13 செ.மீ", "14 செ.மீ", "15 செ.மீ"]', N'4πr² = 2464 → 4 × 22/7 × r² = 2464 → r² = 2464 × 7/88 = 196 → r = 14 செ.மீ. முக்கியக் கற்றல் கருத்து: கோளத்தின் புறப்பரப்பு = 4πr²; r² ஐத் தனிப்படுத்தி, பின்னர் வர்க்கமூலம் எடுக்கவும்.', N'Area and Volume', N'MEDIUM', 28),
    (@gradId, N'Two solid hemispheres of radius 14 cm each are placed together to form a sphere. Find the volume of the resulting sphere. (π = 22/7)', N'["11478⅔ cubic cm", "11488⅔ cubic cm", "11498⅔ cubic cm", "11508⅔ cubic cm"]', 2, N'Two hemispheres of radius 14 cm form a sphere of radius 14 cm. Volume = 4/3 × 22/7 × 14³ = 4/3 × 22/7 × 2744 = 34496/3 = 11498⅔ cubic cm. Key Learning Point: Two equal hemispheres joined at their flat faces form a full sphere of the same radius.', N'ஒவ்வொன்றும் 14 செ.மீ ஆரமுள்ள இரண்டு திண்ம அரைக்கோளங்கள் ஒன்றாக வைக்கப்பட்டு ஒரு கோளம் உருவாகிறது. விளையும் கோளத்தின் கன அளவைக் காண்க. (π = 22/7)', N'["11478⅔ க.செ.மீ", "11488⅔ க.செ.மீ", "11498⅔ க.செ.மீ", "11508⅔ க.செ.மீ"]', N'14 செ.மீ ஆரமுள்ள இரண்டு அரைக்கோளங்கள் 14 செ.மீ ஆரமுள்ள ஒரு கோளத்தை உருவாக்குகின்றன. கன அளவு = 4/3 × 22/7 × 14³ = 4/3 × 22/7 × 2744 = 34496/3 = 11498⅔ க.செ.மீ. முக்கியக் கற்றல் கருத்து: சம ஆரமுள்ள இரண்டு அரைக்கோளங்கள் தட்டையான முகங்களில் இணைந்தால், அதே ஆரமுள்ள முழுக்கோளம் உருவாகிறது.', N'Area and Volume', N'EASY', 29),
    (@gradId, N'A conical vessel of radius 9 cm and height 12 cm is full of water. The water is poured into a cylindrical vessel of radius 6 cm. Find the height of water in the cylinder.', N'["7 cm", "8 cm", "9 cm", "10 cm"]', 2, N'Volume of cone = ⅓ × π × 9² × 12 = ⅓ × π × 81 × 12 = 324π. Volume of water in cylinder = π × 6² × h = 36πh. 36h = 324 → h = 9 cm. Key Learning Point: When liquid is transferred between containers, equate the volumes and solve for the unknown dimension.', N'ஆரம் 9 செ.மீ, உயரம் 12 செ.மீ கொண்ட ஒரு கூம்பு வடிவப் பாத்திரம் முழுவதும் நீர் நிரம்பியுள்ளது. அந்நீர் ஆரம் 6 செ.மீ கொண்ட ஓர் உருளை வடிவப் பாத்திரத்தில் ஊற்றப்படுகிறது. உருளையில் நீரின் உயரத்தைக் காண்க.', N'["7 செ.மீ", "8 செ.மீ", "9 செ.மீ", "10 செ.மீ"]', N'கூம்பின் கன அளவு = ⅓ × π × 9² × 12 = ⅓ × π × 81 × 12 = 324π. உருளையில் நீரின் கன அளவு = π × 6² × h = 36πh. 36h = 324 → h = 9 செ.மீ. முக்கியக் கற்றல் கருத்து: ஒரு பாத்திரத்திலிருந்து மற்றொன்றுக்குத் திரவம் மாற்றப்படும்போது, கன அளவுகளைச் சமப்படுத்தித் தெரியாத அளவைக் காணவும்.', N'Area and Volume', N'MEDIUM', 30);
